// instead of the synth tone. Missing files are a silent no-op (404 → synth keeps playing), same
// drop-in pattern as the music tracks. Volumes tuned per-sample so they sit with the synth SFX.
var _sfxBufs={}, _sfxFilesTried=false;
var _SFX_FILES={ coin:{ vol:0.09 } };   // owner's call 2026-07-26: down 10% from 0.10 (coin runs stack, the tails overlap)
