/* ---------- Game (data-driven, multi-level) ---------- */
/* ---------- Playtest difficulty telemetry — fire-and-forget, no PII (no names, no wallets).
   Tiny events (death: world/x/cause, clear: world/time/deaths) so the digest can point at the
   exact hotspot ("W3 pit at x≈2400") instead of relying on remembered feedback. sendBeacon
   survives tab closes; errors are swallowed — telemetry must never affect play. ---------- */
// ---- SETUP-LANE world gate: is this level's world within the verified wallet's access? ----
// Stable tester build: always true. Setup lane: tier 0 (or no wallet) = worlds 1-2, tier 1 = 1-7,
// tier 2 / 2M CLKN = all. Hidden bonus levels (non "N-M" names) are never gated. Access is read
// LIVE from the premium block's walletState via window.__NQ_ACCESS so a post-buy refresh applies
// without a reload.
function nqWorldAllowed(def){
  if(!window.__NQ_SETUP) return true;
  var m=/^(\d+)-/.exec((def&&def.name)||''); if(!m) return true;
  var w=+m[1], a=null;
  try{ a=(typeof window.__NQ_ACCESS==='function')?window.__NQ_ACCESS():null; }catch(e){}
  if(def&&def.vip){   // ULTRA VIP wing (worlds 13+): needs the VIP grant, not just top tier.
    if(window.__NQ_FORCE_VIP&&(function(){try{return localStorage.getItem('nqLabTune')==='1';}catch(e){return false;}})()) return true;   // QA lever — designer lab only, not the tester lane
    try{ return !!(typeof window.__NQ_VIP==='function'&&window.__NQ_VIP()); }catch(e){ return false; }
  }
  if(a==='all') return true;
  if(Array.isArray(a)&&a.length===2) return w>=a[0]&&w<=a[1];
  return w<=2;
}
// MEGA WHALE is a TOP-TIER holder perk (owner's call 2026-07-19): only the 'all'-worlds tier
// (500k NORMIE / 2M CLKN verified) gets to ride. Same semantics as nqWorldAllowed — outside the
// setup lane (no wallet tiers there) it stays open, and the owner's lab-warp bench bypasses it.
// 🔖 LEVEL RESUME — TIER 2 / VIP perk (owner's ask 2026-07-27: "if you die on the 3rd level of a
// world you go back to the 1st level — can we make it a tier 2 and vip perk that you restart on
// the level you died on"). The base game banks a checkpoint per WORLD (bankCheckpoint, on each
// boss kill), so dying on x-3 replays x-1 and x-2. With this on, the run resumes on the level you
// actually died on.
// Same shape as nqMegaWhaleUnlocked: OUTSIDE the setup lane there are no wallet tiers at all, so
// it stays open (the stable tester build must not get quietly harder than the paid one).
// nqIsVipOrAll is the existing "top tier OR VIP grant" test — reused rather than duplicated so a
// change to what counts as access can never drift between the two.
function nqLevelResumeUnlocked(){
  try{ if(typeof window==='undefined' || !window.__NQ_SETUP) return true; }catch(e){ return true; }
  return nqIsVipOrAll();
}
function nqMegaWhaleUnlocked(){
  if(!window.__NQ_SETUP) return true;
  var a=null; try{ a=(typeof window.__NQ_ACCESS==='function')?window.__NQ_ACCESS():null; }catch(e){}
  return a==='all';
}
function nqTele(ev,d){
  try{
    var who=''; try{ who=localStorage.getItem('nq_tester')||''; }catch(e){}
    var b=JSON.stringify(Object.assign({ev:ev,who:who||undefined},d||{}));
    if(navigator.sendBeacon){ navigator.sendBeacon('/api/nq/telemetry', new Blob([b],{type:'application/json'})); }
    else { fetch('/api/nq/telemetry',{method:'POST',headers:{'content-type':'application/json'},body:b,keepalive:true}).catch(function(){}); }
  }catch(e){}
}

