  /* ---------- The Vault Wyrm (World 5 dragon): stomp its head x3; breathes fireballs ---------- */
  /* ---------- BRIDGE DRAINER boss (World 5) — the one boss that eats the floor ----------
     Every other fight in the game happens on a floor that stays put; the challenge is the boss's
     pattern. This one attacks the ARENA: it siphons the bridge deck away in chunks, so your footing
     shrinks as the fight runs. That is the payoff for a world whose whole identity is planks
     collapsing under you, and it is why 5-3 is no longer a second worm.
     An arena that can become unstandable is worse than an easy one, so four rails hold it up:
       - the CENTRE island is never catalogued as drainable — there is always somewhere to stand
       - drained deck re-lists on a timer
       - landing a stomp restores a chunk, so aggression digs you out of a shrinking arena
       - losing a life restores the WHOLE deck, so you can never respawn into a hole and death-loop
     Static bodies do not follow a tweened sprite, so draining only disables the body and drops the
     image; restoring kills the tween and re-enables it. Same trick the rug plats use. */
  startDrainerBoss:function(){
    var dx=this.def.door, self=this;
    this.cameras.main.flash(420, 200, 90, 30);
    this.player.setPosition(dx-260, GY-40); this.player.setVelocity(0,0);
    var aL=dx-340, aR=dx+40; self.makeArena(aL, aR);
    // Sized + flown at the wyrm's proven head height: the stomp window is a tuned thing and a
    // bigger silhouette floating higher would quietly put it out of jump range.
    var k=this.rugking=this.physics.add.sprite(dx-90, GY-60, 'drainer');
    k.setScale(88/k.height); k.body.setSize(k.width*0.58,k.height*0.58).setOffset(k.width*0.21,k.height*0.20);
    k.body.setAllowGravity(false); k.dir=-1; k.invuln=true; k.setDepth(7);
    var dg=this.addGlow(k,0xff8a30,5); if(dg) this.tweens.add({targets:dg,outerStrength:12,duration:520,yoyo:true,repeat:-1,ease:'Sine.inOut'});
    this.physics.add.overlap(this.player, k, this.bossTouch, null, this);
    this.door.setVisible(false);
    this.bossPips=[]; for(var i=0;i<3;i++) this.bossPips.push(this.hb(this.add.image(W/2-24+i*24, 22, 'heart').setScale(1.4).setDepth(40).setTint(0xff8a30)));
    this.hb(this.add.text(W/2, 42, 'THE BRIDGE DRAINER', {fontFamily:'"Press Start 2P"',fontSize:'10px',color:'#ff8a30'}).setOrigin(.5,0).setDepth(40));
    this.powerBanner('THE BRIDGE DRAINER','IT IS EATING THE BRIDGE — STOMP IT x3','#ff8a30');
    this.rugIntro=true; this.rugGraceUntil=this.time.now+1800;
    var midL=aL+(aR-aL)*0.34, midR=aL+(aR-aL)*0.66;
    this.drainDeck=[];
    this.platforms.children.iterate(function(t){
      if(!t) return;
      if(t.y < GY) return;                      // ground rows only — never the walls or platforms above
      if(t.x < aL+18 || t.x > aR-18) return;    // inside the arena only
      if(t.x > midL && t.x < midR) return;      // the island that always survives
      t.deckHomeY=t.y; t.drained=false; t.restoreAt=0; self.drainDeck.push(t);
    });
    this._dnHomeY=k.y; this._dnState='hover'; this._dnT0=this.time.now;
    this._dnNext=this.time.now+3200; this._dnSide=1;
  },
  drainerTick:function(now,p){
    var k=this.rugking; if(!k||!k.active) return; var self=this;
    // re-list anything whose timer is up, whatever state the fight is in
    for(var i=0;i<(this.drainDeck||[]).length;i++){ var t=this.drainDeck[i];
      if(t.drained && t.restoreAt && now>t.restoreAt) this.restoreDeckTile(t); }
    // drift over the deck tracking the player, bobbing. Velocity rather than repositioning: moving
    // a body by hand each frame clears its collision flags and the stomp stops registering.
    var tx=Phaser.Math.Clamp(p.x, this._arenaL+80, this._arenaR-80);
    k.setVelocityX(Phaser.Math.Clamp((tx-k.x)*1.2, -70, 70));
    var ty=this._dnHomeY + Math.sin(now/420)*6;
    k.setVelocityY((ty-k.y)*4);
    k.setFlipX(p.x>k.x);
    if(this._dnState==='hover'){
      if(now>this._dnNext && !this.rugIntro){ this._dnState='tele'; this._dnT0=now; }
    } else if(this._dnState==='tele'){          // wind-up so a chunk of floor never vanishes unannounced
      if(Math.floor(now/70)%2){ k.setTint(0xffdca8); } else { k.clearTint(); }
      if(now>this._dnT0+700){ k.clearTint(); this._dnState='hover'; this._dnT0=now;
        this.drainChunk();
        this._dnNext=now + (this.bossHP>=3?3400:(this.bossHP===2?2900:2400));   // hungrier as he weakens
      }
    }
  },
  drainChunk:function(){    // siphon the outermost surviving deck on one side, alternating ends
    var self=this, now=this.time.now, mid=(this._arenaL+this._arenaR)/2, side=this._dnSide;
    this._dnSide=-side;
    var live=(this.drainDeck||[]).filter(function(t){ return !t.drained; });
    var cand=live.filter(function(t){ return side<0 ? t.x<mid : t.x>mid; });
    if(!cand.length) cand=live;
    if(!cand.length) return;
    cand.sort(function(a,b){ return side<0 ? a.x-b.x : b.x-a.x; });   // outside-in, so holes open at the edges
    var cols=[]; cand.forEach(function(t){ if(cols.indexOf(t.x)<0 && cols.length<3) cols.push(t.x); });
    var any=false;
    cand.forEach(function(t){
      if(cols.indexOf(t.x)<0) return;
      t.drained=true; t.restoreAt=now+7000; if(t.body) t.body.enable=false; any=true;
      self.tweens.add({targets:t, y:t.deckHomeY+150, alpha:0.05, angle:Phaser.Math.Between(-18,18), duration:520, ease:'Quad.in'});
    });
    if(!any) return;
    this.cameras.main.shake(180,.008);
    this.burst(cols[0], GY-6, 0xff8a30, 16);
    if(SFX&&SFX.stomp) SFX.stomp();
    this.flash('THE DECK IS DRAINING','#ff8a30');
  },
  restoreDeckTile:function(t){
    if(!t) return;
    t.drained=false; t.restoreAt=0; this.tweens.killTweensOf(t);
    t.y=t.deckHomeY; t.angle=0; t.setAlpha(1); if(t.body) t.body.enable=true;
  },
  restoreDeck:function(n){   // n omitted = the whole deck back (used on death so you can't respawn into a hole)
    var drained=(this.drainDeck||[]).filter(function(t){ return t.drained; });
    if(!drained.length) return 0;
    drained.sort(function(a,b){ return a.restoreAt-b.restoreAt; });   // longest-gone comes back first
    var take=(n==null)?drained.length:Math.min(n,drained.length);
    for(var i=0;i<take;i++) this.restoreDeckTile(drained[i]);
    return take;
  },
