    '#nqp-btn{position:fixed;left:89px;top:8px;z-index:9998;background:rgba(20,14,46,.85);color:#ffd23f;border:2px solid #ffb43a;border-radius:10px;'
    + 'font:700 11px system-ui,sans-serif;height:34px;padding:0 10px;cursor:pointer;letter-spacing:.04em}'
    + '#nqp-ov{position:fixed;inset:0;z-index:9999;background:rgba(4,3,10,.82);display:none;align-items:center;justify-content:center}'
    + '#nqp-ov.on{display:flex}'
    + '#nqp-card{width:min(560px,94vw);max-height:88vh;overflow:auto;background:#120e22;border:2px solid #33305a;border-radius:14px;color:#e8e6f5;'
    + 'font-family:system-ui,sans-serif;padding:16px 16px 20px}'
    + '#nqp-card h2{font-size:16px;color:#ffd23f;margin:0 0 2px}'
    + '.nqp-x{float:right;color:#8f89b0;cursor:pointer;font-size:20px;line-height:1}'
    + '.nqp-tabs{display:flex;gap:6px;margin:12px 0}'
    + '.nqp-tab{flex:1;background:#1a1630;border:1px solid #33305a;color:#cbc6e6;border-radius:9px;padding:8px;font-size:12px;cursor:pointer;text-align:center}'
    + '.nqp-tab.on{background:#ffd23f;color:#20142e;border-color:#ffd23f;font-weight:700}'
